def NBitBinary(N):
    def backtrack(n, ones, zeros, path, result):
        if n == 0:
            result.append(path)
            return
        if ones > zeros:
            backtrack(n - 1, ones + 1, zeros, path + '1', result)
        if zeros < ones:
            backtrack(n - 1, ones, zeros + 1, path + '0', result)

    result = []
    backtrack(N, 0, 0, '', result)
    return sorted(result, reverse=True)

